const fs = require('fs');

const input = fs.readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/);
let idx = 0;

function readString() {
    return input[idx++];
}

function readInt() {
    return parseInt(readString(), 10);
}

function readInts() {
    return [readInt(), readInt()];
}

function main() {
    const [k, r] = readInts();
    let i = 1;
    while (true) {
        if ((i * k) % 10 === 0 || (i * k - r) % 10 === 0) {
            console.log(i);
            break;
        }
        i++;
    }
}

main();

