const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let inputLines = [];
rl.on('line', (line) => {
    inputLines.push(line);
}).on('close', () => {
    const tokens = inputLines.join(' ').split(/\s+/);
    let tokenIndex = 0;

    const readString = () => tokens[tokenIndex++];
    const readInt = () => parseInt(readString(), 10);

    const k = readInt();
    const r = readInt();

    let i = 1;
    while (true) {
        if ((i * k) % 10 === 0 || (i * k - r) % 10 === 0) {
            console.log(i);
            break;
        }
        i++;
    }
});

